parameters.jsCode:
// Descarta promociones, redes sociales y spam por etiqueta de Gmail.
// Tolera las dos formas de salida: trigger (subject/from/text/labelIds en
// minúscula) y nodo getAll de prueba (Subject/From/labels en mayúscula).
const rawLabels = $json.labelIds || $json.labels || [];
const labels = rawLabels.map((l) => (typeof l === 'string' ? l : (l && (l.id || l.name)) || ''));
const ruido = ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL', 'CATEGORY_FORUMS', 'SPAM', 'TRASH'];
if (labels.some((l) => ruido.includes(l))) return null;
return { json: {
  id: $json.id,
  threadId: $json.threadId,
  subject: $json.subject || $json.Subject || '(sin asunto)',
  from: $json.from || $json.From || '',
  date: $json.date || $json.Date || '',
  text: ($json.text || $json.textPlain || $json.snippet || '').slice(0, 3000),
} };

const store = $getWorkflowStaticData('global');
const seen = store.emailSeen || {};
const now = Date.now();
const TTL = 14 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(seen)) { if (now - seen[k] > TTL) delete seen[k]; }
const out = [];
for (const item of $input.all()) {
  const key = item.json.id;
  if (!key || seen[key]) continue;
  seen[key] = now;
  out.push({ json: item.json, pairedItem: item.pairedItem });
}
store.emailSeen = seen;
return out;

// El idioma sale del perfil guardado en PostgreSQL (/api/profiles/runtime).
// Los correos se leen de «Deduplicar correos», no de $input: «Perfil (API)»
// es un HTTP Request y sustituye el json de cada item por la respuesta del
// perfil, así que $input aquí trae perfiles, no correos (asunto y texto vacíos).
const perfil = $('Perfil (API)').first().json.profile || {};
const idioma = perfil.idioma || 'es';
return $('Deduplicar correos').all().map((it, idx) => ({
  json: { ...it.json, idioma },
  pairedItem: { item: idx },
}));

