// Lee la respuesta del Automation Center (/api/ai/generate).
// `data` ya viene parseado; `text` es el respaldo. Se acepta ademas el sobre
// antiguo de Gemini para que una importacion a medias no falle en silencio.
function leerIA(r) {
  if (!r) return null;
  if (r.data && typeof r.data === 'object') return r.data;
  const crudo = typeof r.text === 'string'
    ? r.text
    : (r.candidates && r.candidates[0] && r.candidates[0].content
       && r.candidates[0].content.parts && r.candidates[0].content.parts[0]
       && r.candidates[0].content.parts[0].text);
  if (!crudo) return null;
  return JSON.parse(String(crudo).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, ''));
}

let a = {};
try { a = leerIA($json) || {}; } catch (e) {}

let email = {};
try { email = $('Cargar perfil').item.json; } catch (e) { email = {}; }

const ev = a.evento || {};
const crearEvento = ev.crear === true && !!ev.inicio;

return { json: {
  subject: email.subject || '(sin asunto)',
  from: email.from || '',
  idioma: email.idioma || 'es',
  categoria: a.categoria || 'otro',
  prioridad: a.prioridad || 'media',
  requiere_accion: a.requiere_accion === true,
  resumen: a.resumen || '(análisis no disponible)',
  crearEvento,
  evento_titulo: ev.titulo || email.subject || 'Cita',
  evento_inicio: ev.inicio || '',
  evento_fin: ev.fin || ev.inicio || '',
  evento_descripcion: ev.descripcion || ''
} };

// Recompone los datos del correo tras el nodo de Calendar (que reemplaza el
// json por el evento creado, o lo deja pasar si está desactivado, o {error}).
const cal = $json || {};
let email = {};
try { email = $('Parsear análisis').item.json; } catch (e) { email = cal; }
const creado = !!(cal && cal.id && cal.htmlLink);
return { json: {
  ...email,
  evento_creado: creado,
  evento_link: creado ? cal.htmlLink : ''
} };

// Un resumen por ejecucion con todos los correos procesados.
const items = $input.all().map((i) => i.json);
if (items.length === 0) return [];
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Telegram rechaza mensajes de mas de 4096 caracteres. Se parte por bloques
// completos (nunca a mitad de una etiqueta HTML) y se numeran las partes.
function trocear(cabecera, bloques, pie, max = 3900) {
  const SEP = '\n\n━━━━━━━━━━\n\n';
  const partes = [];
  let actual = cabecera;
  let primero = true;
  for (const b of bloques) {
    const candidato = primero ? actual + b : actual + SEP + b;
    if (!primero && candidato.length > max) { partes.push(actual); actual = b; }
    else actual = candidato;
    primero = false;
  }
  if ((actual + pie).length > max) { partes.push(actual); actual = pie.trim(); }
  else actual += pie;
  partes.push(actual);
  return partes.map((texto, i) => ({ json: {
    texto: partes.length > 1 ? texto + '\n<i>(' + (i + 1) + '/' + partes.length + ')</i>' : texto,
  } }));
}
const fecha = new Date().toLocaleString('es-ES', { weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });
const icono = { alta: '🔴', media: '🟡', baja: '🟢' };
const orden = { alta: 0, media: 1, baja: 2 };
items.sort((a, b) => (orden[a.prioridad] ?? 1) - (orden[b.prioridad] ?? 1));

const bloques = items.map((o, i) => {
  let b = `${icono[o.prioridad] || '⚪'} <b>${i + 1}. ${esc(o.subject || '(sin asunto)')}</b>\n`;
  b += `De: ${esc(o.from || '')}\n`;
  b += `${esc(o.categoria || 'otro')} · prioridad ${esc(o.prioridad || 'media')}`;
  if (o.requiere_accion) b += ' · ⚠️ requiere acción';
  b += `\n\n${esc(o.resumen || '')}`;
  if (o.evento_creado) b += `\n\n📅 Evento creado: <a href="${esc(o.evento_link)}">${esc(o.evento_titulo || o.subject)}</a> (${esc(o.evento_inicio || '')})`;
  else if (o.crearEvento) b += `\n\n📅 Cita detectada (evento NO creado): ${esc(o.evento_titulo || '')} (${esc(o.evento_inicio || '')})`;
  return b;
});

const accion = items.filter((o) => o.requiere_accion).length;
return trocear(
  `📧 <b>CORREOS</b>\n<i>${fecha}</i>\n\n━━━━━━━━━━\n\n`,
  bloques,
  `\n\n━━━━━━━━━━\n<i>${items.length} correo(s)${accion ? ' · ' + accion + ' requieren acción' : ''}</i>`,
);

